"""Membership tests with np.isin and set-like filtering of integer IDs."""
import numpy as np

# Order IDs generated by a tiny LCG
def lcg_ids(n, seed=42, modulus=50):
    vals = []
    s = seed
    for _ in range(n):
        s = (s * 73 + 19) % 1009
        vals.append(s % modulus)
    return np.array(vals)

orders = lcg_ids(20)
print("order product ids:")
print(orders)
print(repr(orders))

discontinued = [3, 7, 11, 19, 23, 42]
flag = np.isin(orders, discontinued)
print("discontinued mask:", flag)
print("discontinued orders:", orders[flag])
print("positions:", np.flatnonzero(flag))

# invert=True keeps the rest
active = orders[np.isin(orders, discontinued, invert=True)]
print("active orders:", active)
print("same as ~isin:", np.array_equal(active, orders[~flag]))

# Which requested items exist in stock
stock = np.array([1, 4, 9, 16, 25, 36, 49])
requested = np.array([4, 5, 16, 17, 49])
in_stock = np.isin(requested, stock)
print("requested:", requested)
print("in stock:", in_stock)
print("missing:", requested[~in_stock])

# isin preserves the shape of the first argument
board = np.arange(1, 26).reshape(5, 5)
primes = [2, 3, 5, 7, 11, 13, 17, 19, 23]
is_prime = np.isin(board, primes)
print("board:")
print(board)
print("prime mask:")
print(is_prime.astype(np.int64))
print("primes per row:", is_prime.sum(axis=1))
board_marked = np.where(is_prime, 0, board)
print("primes blanked:")
print(board_marked)

# Related set routines
print("unique orders:", np.unique(orders))
print("intersect with discontinued:", np.intersect1d(orders, discontinued))
print("orders not in stock list:", np.setdiff1d(np.unique(orders), stock))
print("union with stock:", np.union1d(requested, stock))

# Float membership (exact matches only)
grid_pts = np.array([0.0, 0.25, 0.5, 0.75, 1.0])
samples = np.linspace(0.0, 1.0, 9)
print("samples on grid:", samples[np.isin(samples, grid_pts)])
